        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var forecastInvestment = d.forecastInvestment;
            var trendPct = d.trendAllocation / 100;
            var safetyMult = d.safetyStockLevel / 100;
            var mdWeek = d.markdownWeek;

            ds.transformationBudget -= forecastInvestment;

            var accuracyGain = Math.min(0.20, forecastInvestment / 25000);
            var learningBonus = (period - 1) * 0.02;
            var newAccuracy = Math.min(0.85, 0.61 + accuracyGain + learningBonus);
            ds.forecastAccuracy = newAccuracy;

            var safetyEffect = (safetyMult - 1.0) * 0.04;
            var accuracyEffect = (newAccuracy - 0.61) * 0.25;
            var newStockout = Math.max(0.03, 0.11 - safetyEffect - accuracyEffect);
            ds.stockoutRate = newStockout;

            var trendPenalty = (trendPct - 0.25) * 0.3;
            var markdownTimingEffect = (8 - mdWeek) * 0.015;
            var accuracyMdEffect = (newAccuracy - 0.61) * 0.4;
            var newMarkdown = Math.max(0.10, 0.28 - accuracyMdEffect - markdownTimingEffect + trendPenalty);
            ds.markdownRate = newMarkdown;

            var holdingCostPenalty = (safetyMult - 1.0) * 0.015;
            var earlyMdMarginCost = Math.max(0, (8 - mdWeek) * 0.005);
            var marginGain = (0.28 - newMarkdown) * 0.5;
            var newMargin = Math.min(0.58, 0.48 + marginGain - holdingCostPenalty - earlyMdMarginCost);
            ds.grossMargin = newMargin;

            // platform score: average of margin, markdown and stockout progress from the 48/28/11 baseline
            // toward the 52/18/7 targets used by getPerformanceSummary, clamped 0 to 100
            var marginProgress = Math.max(0, Math.min(1, (newMargin - 0.48) / (0.52 - 0.48)));
            var markdownProgress = Math.max(0, Math.min(1, (0.28 - newMarkdown) / (0.28 - 0.18)));
            var stockoutProgress = Math.max(0, Math.min(1, (0.11 - newStockout) / (0.11 - 0.07)));
            var overallScore = Math.round(Math.max(0, Math.min(100, (marginProgress + markdownProgress + stockoutProgress) / 3 * 100)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var turnoverImprovement = (newAccuracy - 0.61) * 3.0 + (1.0 / safetyMult - 0.5) * 0.5;
            ds.inventoryTurnover = Math.min(7.5, 4.2 + turnoverImprovement);

            var baseRevenue = 350000;
            var stockoutLoss = baseRevenue * newStockout;
            var trendUpside = baseRevenue * trendPct * 0.15 * Math.max(0, newAccuracy / 0.61 - 1);
            var revenue = baseRevenue - stockoutLoss + trendUpside;

            if (period === 3) {
                var viralBonus = forecastInvestment > 3000 ? 8000 : 2000;
                revenue += viralBonus;
            }

            var profit = revenue * newMargin - forecastInvestment;
            ds.cumulativeProfit += profit;

            ds.marginHistory.push(Math.round(newMargin * 1000) / 10);
            ds.accuracyHistory.push(Math.round(newAccuracy * 1000) / 10);
            ds.profitHistory.push(Math.round(profit));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                forecastInvestment: forecastInvestment,
                trendAllocation: d.trendAllocation,
                safetyStockLevel: d.safetyStockLevel,
                markdownWeek: mdWeek,
                forecastAccuracy: Math.round(newAccuracy * 1000) / 10,
                stockoutRate: Math.round(newStockout * 1000) / 10,
                markdownRate: Math.round(newMarkdown * 1000) / 10,
                grossMargin: Math.round(newMargin * 1000) / 10,
                inventoryTurnover: Math.round(ds.inventoryTurnover * 10) / 10,
